?=$ev['id']?>">Apply as volunteer</a><a class="btn btn-outline-dark rounded-pill w-100" href="/coordinator/apply.php?event_id=<?=$ev['id']?>">Apply as coordinator</a></div></div><?php endif; ?></div></div><?php require __DIR__.'/../includes/footer.php'; ?>
